reference_solution:
def hash_string_chunks(s,k):
    result=[]
    for start in range(0,len(s),k):
        total=0
        for char in s[start:start+k]:total+=ord(char)-ord('a')
        result.append(chr(ord('a')+total%26))
    return ''.join(result)

